// ============================================================================
// Ore & lake distribution configuration — data-driven terrain generation.
//
// Ore veins are generated by Perlin worms (see terrain.ts). Each ore entry
// controls:
//   - Depth grading: a Gaussian probability curve centered at idealDepthY
//     with spread depthSpread. Multiple ores coexist at overlapping depths,
//     weighted by abundance. Hard limits minDepthY/maxDepthY prevent ores
//     from appearing outside their geological range.
//   - Vein shape: veinLength (worm steps) controls how long/stretched the
//     vein is. veinRadius (deposit radius per step) controls thickness.
//     Common ores get long thick veins; rare ores get short thin ones.
//
// Lake entries are unchanged (blob-carved cavities filled with liquid/gas).
// ============================================================================

import { Material } from "@downdraft/library-sand";

export interface OreEntry {
  material: number;
  name: string;
  // --- Depth grading (world Y coordinates, y increases downward) ---
  idealDepthY: number; // world Y where this ore is most common (Gaussian peak)
  depthSpread: number; // Gaussian standard deviation (in world Y cells)
  minDepthY: number; // hard minimum depth — no ore above this
  maxDepthY: number; // hard maximum depth — no ore below this (99999 = unlimited)
  abundance: number; // relative rarity at peak depth (0-1, higher = more common)
  // --- Vein shape (Perlin worm parameters) ---
  veinLength: number; // max worm steps (longer = more stretched vein)
  veinRadius: number; // deposit radius per step in cells (thicker vein)
}

export interface LakeEntry {
  material: number;
  name: string;
  minChunkY: number;
  maxChunkY: number;
  noiseThreshold: number;
  noiseScale: number;
  octaves: number;
  minSize: number; // minimum lake radius in cells
  maxSize: number; // maximum lake radius in cells
  fillChance: number; // 0-1, probability of a lake center spawning per candidate cell
}

// --- Ore distribution table ---
// Depth is in world Y coordinates. The surface is at ~worldY 38 (in chunk
// cy=0). Stone body starts at ~worldY 44. Each chunk is 128 cells tall.
//
//   worldY  44-500:   shallow (tin, copper, coal)
//   worldY 200-1200:  mid (iron, bauxite)
//   worldY 500-1800:  mid-deep (silver)
//   worldY 800+:      deep (gold, cobalt)
//
// Abundance controls how many worms of each type spawn at a given depth.
// At shallow depths, tin/copper/coal compete with roughly equal weight.
// At gold's ideal depth (~1200), gold and cobalt dominate. This produces
// smooth depth grading with multiple ores coexisting in transition zones.
//
// Vein shape: common ores (tin, copper, coal) get long, thick veins
// (60 steps, radius 2.0) that are easy to find and follow. Rare ores
// (gold, cobalt) get short, thin veins (30 steps, radius 1.0) that are
// harder to find and more rewarding.

