// --- Perlin worm system parameters ---
// These control the global vein generation behavior. Per-ore tuning is in
// OreEntry (veinLength, veinRadius). These are the shared structural params.

export const WORM_CONFIG = {
  // Seed grid spacing: one potential worm spawn point every N world cells.
  // Smaller = more worms = denser ore. 32 → ~16 seed cells per 128-cell chunk.
  seedGrid: 32,
  // Probability that a seed cell actually spawns a worm.
  spawnChance: 0.12,
  // Distance the worm travels per step (in cells). Smaller = smoother path
  // with more overlap between deposits (continuous vein).
  stepSize: 1.5,
  // Maximum direction change per step (radians). Higher = more curvy veins.
  turnRate: 0.35,
  // Spatial frequency of the noise that perturbs the worm's direction.
  // Lower = longer-wavelength curves, higher = tighter wiggles.
  noiseScale: 0.04,
  // Early exit: if a worm has been outside the chunk neighborhood for this
  // many consecutive steps, stop simulating it (optimization).
  maxStepsOutside: 15,
};
